def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_bids = []
    normal_bids = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 100:
                    aggressive_bids.append(bid)
                else:
                    normal_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 20.0))

    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if tightness < 0:
        tightness = 0.0
    if tightness > 1:
        tightness = 1.0

    urgent = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    top_prev = max(prev_bids) if prev_bids else 0.0
    top_normal = max(normal_bids) if normal_bids else 0.0

    if urgent:
        target = max(88.0, top_normal + 4.0)
        if top_prev >= 110:
            target = max(target, 96.0)
        return float(min(budget, target))

    if pressured:
        if supply <= 17:
            target = max(84.0, top_normal + 2.5)
        elif supply <= 20:
            target = max(72.0, top_normal * 0.98 if top_normal > 0 else 72.0)
        else:
            target = 58.0
        return float(min(budget, target))

    if supply <= 16:
        target = max(86.0, top_normal + 3.0)
    elif supply <= 18:
        target = max(76.0, top_normal + 1.5)
    elif supply <= 21:
        target = max(61.0, min(74.0, top_normal * 0.9 if top_normal > 0 else 61.0))
    else:
        target = 42.0

    if len(aggressive_bids) >= 1 and supply >= 20 and hp >= 6:
        target = min(target, 55.0)

    if day >= 8 and hp >= 6:
        target = min(target, 68.0)

    reserve_floor = DAILY_SALARY * 1.2
    if budget < reserve_floor:
        target = min(target, max(28.0, budget * 0.55))

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # collect yesterday's bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # base bid: if hp critical, bid high
    if hp <= 2 or no_water_days >= 2:
        return min(budget, DAILY_SALARY * 0.95)

    # determine yesterday's max bid from alive opponents
    max_prev = max(yesterday_bids) if yesterday_bids else 0

    # adjust based on supply - higher supply means we can bid lower and still win
    if supply >= 20:
        target = max(DAILY_SALARY * 0.5, max_prev * 0.85)
    else:
        target = max(DAILY_SALARY * 0.6, max_prev * 0.95 + 1)

    # ensure we don't overspend
    bid = min(budget, target)
    return int(bid)
